function lighten(hex,amt){return colorShift(hex,amt)}function darken(hex,amt){return colorShift(hex,-amt)}function colorShift(hex,amt){const n=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(n>>16)+amt)),g=Math.max(0,Math.min(255,((n>>8)&255)+amt)),b=Math.max(0,Math.min(255,(n&255)+amt));return`rgb(${r},${g},${b})`}
let lastTime=0;
function update(dt){for(const f of fruits){f.age+=dt;f.vy+=gravity*dt;f.x+=f.vx*dt;f.y+=f.vy*dt;const left=boundL()+f.r,right=boundR()-f.r;if(f.x<left){f.x=left;f.vx=Math.abs(f.vx)*.28}else if(f.x>right){f.x=right;f.vx=-Math.abs(f.vx)*.28}const floor=floorY()-f.r;if(f.y>floor){f.y=floor;if(f.vy>55)playTone(160,.025);f.vy*=-.19;if(Math.abs(f.vy)<32)f.vy=0;f.vx*=.91;if(Math.abs(f.vx)<4)f.vx=0}f.settled=Math.abs(f.vy)<15&&Math.abs(f.vx)<18}
// Fruit-to-fruit collisions and pair merges
for(let i=0;i<fruits.length;i++){const a=fruits[i];if(!a||a.merging)continue;for(let j=i+1;j<fruits.length;j++){const b=fruits[j];if(!b||b.merging)continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy),min=a.r+b.r;if(d>=min)continue;if(d<.01){dx=.01;d=.01}if(a.level===b.level&&a.age>.18&&b.age>.18){merge(a,b);break}const nx=dx/d,ny=dy/d,overlap=min-d,m1=a.r*a.r,m2=b.r*b.r,total=m1+m2;a.x-=nx*overlap*(m2/total);a.y-=ny*overlap*(m2/total);b.x+=nx*overlap*(m1/total);b.y+=ny*overlap*(m1/total);const rel=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(rel<0){const impulse=-(1.2)*rel/(1/m1+1/m2);a.vx-=impulse*nx/m1;a.vy-=impulse*ny/m1;b.vx+=impulse*nx/m2;b.vy+=impulse*ny/m2}a.vx*=.99;b.vx*=.99}}
for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt}particles=particles.filter(p=>p.life>0);
const danger=118;const threatening=fruits.some(f=>f.y-f.r<danger&&f.age>1.5&&f.settled);if(threatening){if(!update.dangerSince)update.dangerSince=performance.now();if(performance.now()-update.dangerSince>1600)gameOver()}else update.dangerSince=0;
}
function render(){ctx.clearRect(0,0,W,H);const floor=floorY(); // soft floor shadow
ctx.fillStyle='#77966d12';ctx.beginPath();ctx.ellipse(W/2,floor+9,W*.36,17,0,0,Math.PI*2);ctx.fill();
// soft floating dust
for(let i=0;i<7;i++){const x=((i*71+33)%W),y=((i*97+19)%(H-130))+105;ctx.fillStyle='#fff9';ctx.beginPath();ctx.arc(x,y,1.1,0,Math.PI*2);ctx.fill()}
for(const f of fruits)drawFruit(f);for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*2);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size*Math.min(1,p.life),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function tick(now){const dt=Math.min(.03,(now-lastTime)/1000||0);lastTime=now;if(!ended&&fruits.length)update(dt);render();requestAnimationFrame(tick)}
function gameOver(){if(ended)return;ended=true;document.getElementById('modalIcon').textContent='🍉';document.getElementById('modalTitle').textContent='Bowl’s full!';document.getElementById('modalText').innerHTML=`You scored <strong>${score.toLocaleString()}</strong> points.<br>Ready for another juicy round?`;document.getElementById('restart').textContent='Play again';overlay.classList.add('active')}
function reset(){fruits=[];particles=[];score=0;scoreEl.textContent='0';ended=false;mergeCount=0;update.dangerSince=0;overlay.classList.remove('active');dropLevel=Math.random()<.5?0:1;document.getElementById('dropper').textContent=emojis[dropLevel];setNext();lastDrop=0;}
function movePointer(e){const rect=canvas.getBoundingClientRect();const x=e.clientX-rect.left;aimX=Math.max(boundL()+12,Math.min(boundR()-12,x));positionDropper()}
canvas.addEventListener('pointermove',movePointer);canvas.addEventListener('pointerdown',e=>{e.preventDefault();movePointer(e);drop()});canvas.addEventListener('pointerup',e=>{if(e.pointerType==='touch')drop()});
window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();drop()}if(e.code==='ArrowLeft')aimX=Math.max(boundL()+20,aimX-22);if(e.code==='ArrowRight')aimX=Math.min(boundR()-20,aimX+22);positionDropper()});
window.addEventListener('resize',resize);document.getElementById('restart').onclick=reset;document.getElementById('restartSmall').onclick=reset;
document.getElementById('helpBtn').onclick=()=>{ended=true;document.getElementById('modalIcon').textContent='🍒';document.getElementById('modalTitle').textContent='How to play';document.getElementById('modalText').innerHTML='Move to aim, then tap or click to drop.<br>Match two of the same fruit to merge!';document.getElementById('restart').textContent='Let’s play';overlay.classList.add('active')};
document.getElementById('soundTop').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';showToast(soundOn?'Sound on':'Sound off');if(soundOn)playTone(600)};
document.getElementById('shareBtn').onclick=async()=>{const text=`I scored ${score.toLocaleString()} in Fruit Drop! 🍐`;try{if(navigator.share)await navigator.share({title:'Fruit Drop',text});else{await navigator.clipboard.writeText(text);showToast('Score copied — share the juice!')}}catch(e){showToast(text)}};
resize();dropLevel=0;setNext();positionDropper();requestAnimationFrame(tick);
</script></body></html>

